#include <set>
#include <vector>

std::vector<int> duplicates(const std::vector<int>& values)
{
    std::set<int> seen{};
    std::set<int> repeated{};
    for (int value : values)
    {
        if (!seen.insert(value).second)
        {
            repeated.insert(value);
        }
    }
    return std::vector<int>(repeated.begin(), repeated.end());
}

unitTests:
TEST("finds the repeats") { CHECK_EQ(duplicates({ 4, 1, 4, 2, 1, 4 }), (std::vector<int>{ 1, 4 })); }
TEST("sorted, each listed once") { CHECK_EQ(duplicates({ 9, 3, 9, 3, 9, 3, 1 }), (std::vector<int>{ 3, 9 })); }
TEST("nothing repeats") { CHECK(duplicates({ 1, 2, 3 }).empty()); CHECK(duplicates({}).empty()); }

